contract.source:
{
  "notes": "Contract inferred from observed failures: not logged in, payment method not accepted, and episode ended after order placement when order_status is already placed. Success requires login, an unplaced order, a valid payment method and address, non-empty cart covered by stock, and a valid coupon if present. On success the order slot is populated from the pre-state cart/checkout and the cart and stock are updated.",
  "postcondition": {
    "args": [
      {
        "left": {
          "var": "order_status",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "const": "placed"
        }
      },
      {
        "left": {
          "var": "order_items",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "var": "cart",
          "when": "before"
        }
      },
      {
        "left": {
          "var": "order_size",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "var": "cart_size",
          "when": "before"
        }
      },
      {
        "left": {
          "var": "order_total",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "var": "checkout_total",
          "when": "before"
        }
      },
      {
        "left": {
          "var": "order_payment_method",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "var": "payment_method",
          "when": "before"
        }
      },
      {
        "arg": {
          "var": "cart",
          "when": "after"
        },
        "op": "is_empty"
      },
      {
        "left": {
          "var": "cart_size",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "const": 0
        }
      },
      {
        "left": {
          "var": "cart_subtotal",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "const": 0
        }
      },
      {
        "left": {
          "var": "checkout_total",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "const": 0
        }
      },
      {
        "left": {
          "var": "stock",
          "when": "after"
        },
        "op": "eq",
        "right": {
          "left": {
            "var": "stock",
            "when": "before"
          },
          "op": "difference",
          "right": {
            "var": "cart",
            "when": "before"
          }
        }
      },
      {
        "op": "unchanged",
        "vars": [
          "card_limit",
          "wallet_balance",
          "payment_method",
          "shipping_address",
          "coupon_code",
          "logged_in"
        ]
      }
    ],
    "op": "and"
  },
  "precondition": {
    "args": [
      {
        "arg": {
          "var": "logged_in",
          "when": "before"
        },
        "op": "is_true"
      },
      {
        "left": {
          "var": "order_status",
          "when": "before"
        },
        "op": "ne",
        "right": {
          "const": "placed"
        }
      },
      {
        "op": "in_set",
        "set": "payment_methods",
        "value": {
          "var": "payment_method",
          "when": "before"
        }
      },
      {
        "op": "in_set",
        "set": "addresses",
        "value": {
          "var": "shipping_address",
          "when": "before"
        }
      },
      {
        "arg": {
          "arg": {
            "var": "cart",
            "when": "before"
          },
          "op": "is_empty"
        },
        "op": "not"
      },
      {
        "available": {
          "var": "stock",
          "when": "before"
        },
        "op": "covers",
        "required": {
          "var": "cart",
          "when": "before"
        }
      },
      {
        "args": [
          {
            "arg": {
              "var": "coupon_code",
              "when": "before"
            },
            "op": "is_null"
          },
          {
            "op": "in_set",
            "set": "coupon_codes",
            "value": {
              "var": "coupon_code",
              "when": "before"
            }
          }
        ],
        "op": "or"
      }
    ],
    "op": "and"
  },
  "skill": "place_order"
}
